#if UNITY_EDITOR || DEVELOPMENT_BUILD
using System;using System.IO;using System.Linq;using System.Collections;using UnityEngine;using UnityEngine.UI;
public class StadiaCapture:MonoBehaviour {
 string folder;int checks;void Check(bool b,string s){if(!b)throw new Exception(s);checks++;}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Boot(){if(!Environment.GetCommandLineArgs().Contains("-stadia-check"))return;var go=new GameObject("Stadia check");DontDestroyOnLoad(go);go.AddComponent<StadiaCapture>();}
 IEnumerator Start(){Application.runInBackground=true;folder=Path.Combine(Application.dataPath,"../StadiaChecks");Directory.CreateDirectory(folder);yield return null;SaveMenu.StartCampaign(false);yield return new WaitForSecondsRealtime(2);try{var s=VariableSingleton.Instance.CaptureState();s.turn=16;VariableSingleton.Instance.RestoreValidated(s);Screen.SetResolution(1600,900,false);ConstantinopleVicinityUI.Show();}catch(Exception e){Fail(e);yield break;}yield return new WaitForSecondsRealtime(.6f);
 try {Check(!ConstantinopleVicinityUI.Sites.Any(s=>s.Id=="studios"),"monastery retired");var site=ConstantinopleVicinityUI.Sites.First(s=>s.Id=="stadia");Check(site.Name=="Fortress Stadia"&&site.Point.x==.08f&&site.Route=="visit","Stadia anchor and route");var camps=FindObjectsOfType<VicinityCampArt>();Check(camps.Length==6,"six camps");foreach(var camp in camps){ImperialTheme.Button(camp.GetComponent<Button>());Check(camp.GetComponentsInChildren<ImperialFrame>().Length==0,"late theme preserves frameless camp");Check(camp.GetComponent<Button>().transition==Selectable.Transition.None,"silhouette owns hover");}Check(Resources.Load<Texture2D>("UI/Maps/VicinityLocations/stadia")!=null,"art loaded");}catch(Exception e){Fail(e);yield break;}
 yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.Combine(folder,"map.png"));yield return new WaitForSecondsRealtime(.3f);VicinityLocations.Show(ConstantinopleVicinityUI.Sites.First(s=>s.Id=="stadia"));yield return new WaitForSecondsRealtime(.3f);ScreenCapture.CaptureScreenshot(Path.Combine(folder,"fortress.png"));yield return new WaitForSecondsRealtime(.3f);try{Check(VicinityLocations.Close()&&ConstantinopleVicinityUI.IsOpen,"return preserves map");File.WriteAllText(Path.Combine(folder,"checks.txt"),"STADIA_CHECKS "+checks+" passed");}catch(Exception e){Fail(e);yield break;}Application.Quit();
 }void Fail(Exception e){File.WriteAllText(Path.Combine(folder,"checks.txt"),e.ToString());Application.Quit(1);}
}
#endif
